-- POTENT VOICE core schema (parity copy of what is live in Supabase: migrations voice_core, voice_confirm_rpc, voice_notifications_kind).
-- Requires voice-billing.sql first (voice_plans etc.) and the existing organizations/jobs tables. Run only on a project that does not have it yet.
create extension if not exists btree_gist;
create table if not exists public.voice_agent_config (org_id uuid primary key references organizations(id) on delete cascade, agent_name text not null default 'POTENT AI Assistant', greeting text, disclosure text, voice text default 'marin', business_hours jsonb not null default '{}', transfer_number text, human_available boolean not null default false, recording_enabled boolean not null default false, recording_consent_confirmed boolean not null default false, outbound_enabled boolean not null default false, outbound_compliance_confirmed boolean not null default false, emergency_stop boolean not null default false, ai_enabled boolean not null default true, max_call_minutes integer, retention_days integer not null default 30, spend_alert_cents integer, provider_telephony text not null default 'twilio', provider_ai text not null default 'openai-realtime', service_area jsonb not null default '{"states":["GA"],"counties":[]}', updated_by text, updated_at timestamptz not null default now(), version integer not null default 1, settings jsonb not null default '{}');
create table if not exists public.voice_vehicle_profiles (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, fleet_vehicle_id text, name text not null, kind text not null default 'company' check (kind in ('company','contractor')), max_payload_lb integer not null, interior_l_in numeric, interior_w_in numeric, interior_h_in numeric, door_w_in numeric, door_h_in numeric, equipment jsonb not null default '{}', service_area jsonb not null default '{"states":["GA"]}', authorized boolean not null default false, verified_by text, verified_at timestamptz, interstate_authorized boolean not null default false, active boolean not null default true, version integer not null default 1, updated_by text, updated_at timestamptz not null default now());
create table if not exists public.voice_sessions (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, provider text not null default 'twilio', provider_call_id text, direction text not null default 'inbound' check (direction in ('inbound','outbound')), from_number text, to_number text, state text not null default 'ringing' check (state in ('ringing','active','handoff','ended','failed','rejected')), end_reason text, customer_id uuid, lead_id uuid, intake jsonb not null default '{}', quote jsonb, confirmed_by_caller boolean not null default false, summary text, outcome text, sentiment text, started_at timestamptz not null default now(), answered_at timestamptz, ended_at timestamptz, seconds integer, test_mode boolean not null default false, created_at timestamptz not null default now(), unique (provider, provider_call_id));
create index if not exists voice_sessions_org_time on public.voice_sessions (org_id, started_at desc);
create index if not exists voice_sessions_live on public.voice_sessions (org_id) where state in ('ringing','active','handoff');
create table if not exists public.voice_events (id bigint generated always as identity primary key, org_id uuid not null, session_id uuid references voice_sessions(id) on delete cascade, event_key text not null, kind text not null, detail jsonb, created_at timestamptz not null default now(), unique (org_id, event_key));
create table if not exists public.voice_transcripts (id bigint generated always as identity primary key, org_id uuid not null, session_id uuid not null references voice_sessions(id) on delete cascade, seq integer not null, role text not null check (role in ('caller','agent','system')), text text not null, created_at timestamptz not null default now(), unique (session_id, seq));
create table if not exists public.voice_tool_executions (id bigint generated always as identity primary key, org_id uuid not null references organizations(id) on delete cascade, session_id uuid references voice_sessions(id) on delete cascade, tool text not null, call_key text not null, args jsonb, result jsonb, ok boolean not null default false, error text, ms integer, created_at timestamptz not null default now(), unique (org_id, call_key));
create table if not exists public.voice_quotes (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, session_id uuid references voice_sessions(id), number text not null, input jsonb not null, lines jsonb not null, total_cents integer not null, miles numeric, miles_source text, settings_version text, status text not null default 'offered' check (status in ('offered','accepted','expired','declined')), expires_at timestamptz not null, created_at timestamptz not null default now(), unique (org_id, number));
create table if not exists public.voice_bookings (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, session_id uuid references voice_sessions(id), quote_id uuid references voice_quotes(id), idem_key text not null, reference text not null, job_id text, status text not null default 'pending_review' check (status in ('pending_review','confirmed','cancelled','needs_change')), review_reason text, vehicle_profile_id uuid references voice_vehicle_profiles(id), window_start timestamptz, window_end timestamptz, customer_name text, customer_phone text, customer_email text, snapshot jsonb not null, confirmation_sent_at timestamptz, created_at timestamptz not null default now(), confirmed_at timestamptz, unique (org_id, idem_key), unique (org_id, reference));
create table if not exists public.voice_capacity_holds (id uuid primary key default gen_random_uuid(), org_id uuid not null, vehicle_profile_id uuid not null references voice_vehicle_profiles(id), booking_id uuid not null references voice_bookings(id) on delete cascade, window_start timestamptz not null, window_end timestamptz not null, status text not null default 'held' check (status in ('held','released')), constraint voice_no_double_booking exclude using gist (vehicle_profile_id with =, tstzrange(window_start, window_end) with &&) where (status = 'held'));
create table if not exists public.voice_handoffs (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, session_id uuid references voice_sessions(id), reason text not null, summary text, status text not null default 'requested' check (status in ('requested','accepted','declined','missed','completed','callback')), requested_at timestamptz not null default now(), resolved_at timestamptz, resolved_by text);
create table if not exists public.voice_callbacks (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, session_id uuid references voice_sessions(id), name text, phone text not null, reason text, preferred_time text, status text not null default 'open' check (status in ('open','done','cancelled')), created_at timestamptz not null default now(), done_by text, done_at timestamptz);
create table if not exists public.voice_knowledge_documents (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, category text not null, title text not null, body text not null, version integer not null default 1, status text not null default 'draft' check (status in ('draft','approved','retired')), effective_from date, approved_by text, approved_at timestamptz, created_by text, created_at timestamptz not null default now());
create table if not exists public.voice_consent_records (id bigint generated always as identity primary key, org_id uuid not null, phone text not null, kind text not null check (kind in ('call','recording','sms','email')), granted boolean not null, source text, session_id uuid, created_at timestamptz not null default now());
create table if not exists public.voice_suppression_records (id bigint generated always as identity primary key, org_id uuid not null, phone text not null, reason text, source text, created_at timestamptz not null default now(), unique (org_id, phone));
create table if not exists public.voice_campaigns (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, name text not null, kind text not null default 'followup' check (kind in ('callback','missed_call','quote_followup','reminder','qualification')), status text not null default 'draft' check (status in ('draft','pending_approval','approved','running','paused','stopped','done')), call_window jsonb not null default '{"tz":"America/New_York","end":"17:00","start":"09:00"}', max_attempts integer not null default 2, approved_by text, created_by text, created_at timestamptz not null default now());
create table if not exists public.voice_campaign_contacts (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references voice_campaigns(id) on delete cascade, org_id uuid not null, phone text not null, name text, consent_ref text, attempts integer not null default 0, status text not null default 'queued' check (status in ('queued','called','done','skipped','suppressed')), outcome text, last_attempt_at timestamptz, unique (campaign_id, phone));
create table if not exists public.voice_provider_health (id bigint generated always as identity primary key, org_id uuid, provider text not null, kind text not null, ok boolean not null, detail text, created_at timestamptz not null default now());
create table if not exists public.voice_notifications_sent (id bigint generated always as identity primary key, org_id uuid not null, booking_id uuid, channel text not null, to_addr text not null, status text not null default 'sent', error text, created_at timestamptz not null default now(), kind text not null default 'request');
create unique index if not exists voice_notifications_sent_bk_ch_kind on public.voice_notifications_sent (booking_id, channel, kind);
-- Row-level security on, no policies: only the server (service role) can read or write.
do $$ declare t text; begin foreach t in array array['voice_agent_config','voice_vehicle_profiles','voice_sessions','voice_events','voice_transcripts','voice_tool_executions','voice_quotes','voice_bookings','voice_capacity_holds','voice_handoffs','voice_callbacks','voice_knowledge_documents','voice_consent_records','voice_suppression_records','voice_campaigns','voice_campaign_contacts','voice_provider_health','voice_notifications_sent'] loop execute format('alter table public.%I enable row level security', t); end loop; end $$;

create or replace function public.voice_confirm_booking(p_booking uuid, p_job_id text, p_job jsonb) returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare b voice_bookings%rowtype;
begin
  select * into b from voice_bookings where id = p_booking for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if b.status = 'confirmed' then return jsonb_build_object('ok', true, 'duplicate', true, 'job_id', b.job_id); end if;
  if b.status <> 'pending_review' then return jsonb_build_object('ok', false, 'error', 'bad_state'); end if;
  if b.vehicle_profile_id is null or b.window_start is null or b.window_end is null then return jsonb_build_object('ok', false, 'error', 'no_window'); end if;
  begin
    insert into voice_capacity_holds (org_id, vehicle_profile_id, booking_id, window_start, window_end) values (b.org_id, b.vehicle_profile_id, b.id, b.window_start, b.window_end);
  exception when exclusion_violation then
    return jsonb_build_object('ok', false, 'error', 'conflict');
  end;
  insert into jobs (id, org_id, customer, phone, email, service, service_name, origin, destination, speed, base_price, final_price, status, payment_status, date, time_slot, notes, miles, est_total_lbs, trips, scheduled_time, is_business, company_name, customer_type)
  values (p_job_id, b.org_id, p_job->>'customer', p_job->>'phone', p_job->>'email', p_job->>'service', p_job->>'service_name', p_job->>'origin', p_job->>'destination', p_job->>'speed',
          (p_job->>'base_price')::numeric, (p_job->>'final_price')::numeric, 'Confirmed', 'pending', (p_job->>'date')::date, p_job->>'time_slot', p_job->>'notes', (p_job->>'miles')::numeric,
          (p_job->>'est_total_lbs')::numeric, 1, b.window_start, coalesce((p_job->>'is_business')::boolean, false), p_job->>'company_name', coalesce(p_job->>'customer_type','business'));
  update voice_bookings set status = 'confirmed', job_id = p_job_id, confirmed_at = now(), review_reason = null where id = b.id;
  return jsonb_build_object('ok', true, 'job_id', p_job_id);
end $function$;
create or replace function public.voice_release_booking(p_booking uuid, p_reason text) returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare b voice_bookings%rowtype;
begin
  select * into b from voice_bookings where id = p_booking for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  update voice_capacity_holds set status = 'released' where booking_id = b.id;
  update voice_bookings set status = 'cancelled', review_reason = p_reason where id = b.id;
  if b.job_id is not null then update jobs set status = 'Cancelled' where id = b.job_id and org_id = b.org_id; end if;
  return jsonb_build_object('ok', true);
end $function$;
revoke execute on function public.voice_confirm_booking(uuid, text, jsonb), public.voice_release_booking(uuid, text) from public, anon, authenticated;
